//! Phase 18D-1 oracle: the Rust crew engine must reproduce the Go engine's CLI
//! output byte for byte for the whole corpus.
//!
//! Goldens are generated by `scripts/crew-host-oracle.py` (which runs the Go
//! `forseti-crew validate -f FILE --explain`) and live in
//! `host/tests/golden/<kind>/<crew>.json`. This test is the Rust half: it
//! replays every record through `forseti_host::crew::validate` and diffs
//! stdout / stderr / exit.

use std::path::{Path, PathBuf};

fn repo_root() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .parent()
        .expect("host/ has a parent")
        .to_path_buf()
}

#[test]
fn rust_engine_matches_go_goldens() {
    let root = repo_root();
    let golden = root.join("host/tests/golden");

    // Goldens record the corpus paths relative to the repo root, because that
    // is the argument the Go CLI was given — run the Rust engine from there.
    std::env::set_current_dir(&root).expect("chdir repo root");

    let mut files: Vec<PathBuf> = Vec::new();
    collect(&golden, &mut files);
    files.sort();
    assert!(!files.is_empty(), "no goldens under {}", golden.display());

    let mut failures: Vec<String> = Vec::new();
    for path in &files {
        let text = std::fs::read_to_string(path).expect("read golden");
        let rec: serde_json::Value = serde_json::from_str(&text).expect("parse golden");
        let rel = path
            .strip_prefix(&root)
            .unwrap_or(path)
            .display()
            .to_string();

        let file = rec["file"].as_str().expect("golden .file");
        let exit = rec["exit"].as_i64().expect("golden .exit") as i32;
        let stdout = rec["stdout"].as_str().expect("golden .stdout");
        let stderr = rec["stderr"].as_str().expect("golden .stderr");
        let explain = rec["argv"]
            .as_array()
            .map(|a| a.iter().any(|v| v == "--explain"))
            .unwrap_or(false);

        let got = forseti_host::crew::validate(file, explain);
        if got.stdout != stdout {
            failures.push(format!(
                "{rel}: stdout\n  want {stdout:?}\n  got  {:?}",
                got.stdout
            ));
        }
        if got.stderr != stderr {
            failures.push(format!(
                "{rel}: stderr\n  want {stderr:?}\n  got  {:?}",
                got.stderr
            ));
        }
        if got.exit != exit {
            failures.push(format!("{rel}: exit want {exit} got {}", got.exit));
        }

        // `prompts` pins the prompt templates: `validate --explain` cannot see a
        // role/pattern text drift, so compare the resolved node prompts against
        // the Go dump (parsed, so JSON escaping never matters).
        let prompts = &rec["prompts"];
        let pexit = prompts["exit"].as_i64().expect("golden .prompts.exit") as i32;
        let pstdout = rec["prompts"]["stdout"]
            .as_str()
            .expect("golden .prompts.stdout");
        let pstderr = rec["prompts"]["stderr"]
            .as_str()
            .expect("golden .prompts.stderr");
        match forseti_host::crew::load(&std::fs::read_to_string(file).unwrap_or_default()) {
            Err(err) => {
                if p_exit_ok(pexit) {
                    failures.push(format!(
                        "{rel}: prompts valid in Go but Rust errored: {err}"
                    ));
                } else if !p_stderr_matches(&err, pstderr) {
                    failures.push(format!(
                        "{rel}: prompts stderr\n  want {pstderr:?}\n  got  {err:?}"
                    ));
                }
            }
            Ok(crew) => {
                if !p_exit_ok(pexit) {
                    failures.push(format!(
                        "{rel}: prompts invalid in Go ({pstderr:?}) but Rust loaded it"
                    ));
                    continue;
                }
                let json: serde_json::Value =
                    serde_json::from_str(pstdout).expect("golden prompts stdout is JSON");
                let agents = json["agents"].as_array().expect("golden prompts .agents");
                if agents.len() != crew.agents.len() {
                    failures.push(format!(
                        "{rel}: prompts node count want {} got {}",
                        agents.len(),
                        crew.agents.len()
                    ));
                    continue;
                }
                for (i, want) in agents.iter().enumerate() {
                    let got = &crew.agents[i];
                    let wn = want["name"].as_str().unwrap_or_default();
                    let wp = want["prompt"].as_str().unwrap_or_default();
                    if got.name != wn || got.prompt != wp {
                        failures.push(format!(
                            "{rel}: prompt #{i}\n  want name={wn:?} prompt={wp:?}\n  got  name={:?} prompt={:?}",
                            got.name, got.prompt
                        ));
                    }
                }
            }
        }
    }
    assert!(
        failures.is_empty(),
        "{} golden mismatch(es):\n{}",
        failures.len(),
        failures.join("\n")
    );
}

fn p_exit_ok(exit: i32) -> bool {
    exit == 0
}

/// The Go `prompts` command prints `INVALID: <err>` on any load failure.
fn p_stderr_matches(err: &str, want: &str) -> bool {
    want == format!("INVALID: {err}\n")
}

fn collect(dir: &Path, out: &mut Vec<PathBuf>) {
    for entry in std::fs::read_dir(dir).unwrap_or_else(|e| panic!("read {}: {e}", dir.display())) {
        let p = entry.expect("dir entry").path();
        if p.is_dir() {
            collect(&p, out);
        } else if p.extension().is_some_and(|e| e == "json") {
            out.push(p);
        }
    }
}
